content.text:
{
  "name": "串口转 I2C 桥接器",
  "name_en": "Serial-to-I2C Bridge",
  "manufacturer": "",
  "description": "一种基于 Arduino 的串口到 I2C 通信桥接设备，用于在实验系统中通过串口与 I2C 总线外设通信、读写寄存器并检查总线连接状态。",
  "description_en": "An Arduino-based serial-to-I2C communication bridge used in laboratory setups to access I2C bus peripherals over a serial link, read and write registers, and verify bus connectivity.",
  "actions": [
    {
      "action_name": "auto-i2c_address",
      "description": "获取/设置目标 I2C 设备地址。",
      "description_en": "Get/set the target I2C device address."
    },
    {
      "action_name": "auto-query_i2c",
      "description": "发送 I2C 查询消息并检查传输返回状态。",
      "description_en": "Send an I2C query message and check the transmission return status."
    },
    {
      "action_name": "auto-read_register",
      "description": "读取指定 I2C 寄存器的数据。",
      "description_en": "Read data from the specified I2C register."
    },
    {
      "action_name": "auto-write_register",
      "description": "向指定 I2C 寄存器写入数据。",
      "description_en": "Write data to the specified I2C register."
    },
    {
      "action_name": "auto-check_i2c_connection",
      "description": "检查桥接器到 I2C 总线设备的连接是否正常。",
      "description_en": "Check whether the connection from the bridge to the I2C bus device is working properly."
    }
  ],
  "tag_hints": [
    "serial to I2C bridge",
    "Arduino-based interface",
    "I2C register access",
    "bus communication adapter",
    "embedded peripheral control"
  ]
}

